CREATE FUNCTION composite_grant_commit_failure() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'controlled deferred grant failure'; END $$;
CREATE CONSTRAINT TRIGGER composite_grant_commit_failure
AFTER INSERT ON iam_session_grant DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION composite_grant_commit_failure();

TRUNCATE iam_account, iam_invitation, iam_session_grant, iam_operation, iam_audit RESTART IDENTITY;
UPDATE iam_administration_guard SET initialized=false WHERE id=1;
UPDATE iam_login_protection SET generation=NULL,blocked_until='infinity' WHERE id=1;
